import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.DTdEDYjJ.js";const c=JSON.parse('{"title":"模型与 API 连接","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md"}'),d={name:"guide/models.md"};function o(h,t,n,l,p,r){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="模型与-api-连接" tabindex="-1">模型与 API 连接 <a class="header-anchor" href="#模型与-api-连接" aria-label="Permalink to &quot;模型与 API 连接&quot;">​</a></h1><p>OpenBot 可以连接你选择的兼容 API 服务。每个 Bot 分别选择连接、模型和执行内核；主 Bot 与执行 Bot 可以使用不同服务。API 额度与订阅由你向服务商取得，OpenBot 目前没有官方账号、托管模型或代售入口。</p><p>先完成<a href="/openbot/guide/quickstart.html">快速开始</a>，再按照本页配置一条连接。接入成功后，需要网页操作的 Bot 还要单独<a href="/openbot/guide/computer-use.html">启用浏览器工具</a>。</p><h2 id="准备三个值" tabindex="-1">准备三个值 <a class="header-anchor" href="#准备三个值" aria-label="Permalink to &quot;准备三个值&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填写内容</th><th>核对方法</th></tr></thead><tbody><tr><td>Base URL</td><td>服务商提供的兼容 API 基础地址</td><td>保留服务商要求的路径，例如 <code>/v1</code>；不要填聊天网页地址</td></tr><tr><td>API Key</td><td>你在该服务获得的密钥</td><td>确认属于该地址对应的服务与项目</td></tr><tr><td>模型名称</td><td>服务端接受的完整模型 ID</td><td>按服务商控制台或 API 文档填写，名称展示相似不代表 ID 相同</td></tr></tbody></table><p>Base URL 只接受 <code>http</code> 或 <code>https</code>，不能在地址里嵌入账号、查询参数或片段。是否支持工具、图像和所需参数，取决于所选模型与服务的实际兼容性；普通文字回复成功只证明聊天路径可用。</p><h2 id="在界面中保存连接" tabindex="-1">在界面中保存连接 <a class="header-anchor" href="#在界面中保存连接" aria-label="Permalink to &quot;在界面中保存连接&quot;">​</a></h2><ol><li>选中要配置的 Bot，打开它的模型接入设置。</li><li>新建命名 API 连接，填写易辨认的名称、Base URL、Key 和默认模型。</li><li>保存连接，并在当前 Bot 的“这个 bot 使用”中选择它。</li><li>在 Bot 的“模型名称”中确认实际模型；自定义模型填写完整 ID。</li><li>先发送一句短的文字请求，收到真实回复后，再测试工具任务。</li></ol><p>“测试连接”检查接口可达性，不能代替实际模型回复，也不能证明浏览器能力。需要验证模型与执行内核组合时，使用<a href="/openbot/guide/harness.html#验证当前组合">内核指南中的主动健康检测</a>。检测会发起实际请求，使用少量服务额度。</p><h2 id="每个-bot-如何选模型" tabindex="-1">每个 Bot 如何选模型 <a class="header-anchor" href="#每个-bot-如何选模型" aria-label="Permalink to &quot;每个 Bot 如何选模型&quot;">​</a></h2><p>主进程根据已保存配置解析请求，界面临时传入的模型名和温度不能覆盖它。</p><table tabindex="0"><thead><tr><th>Bot 的配置</th><th>实际选择</th></tr></thead><tbody><tr><td><code>providerId</code> 指向命名连接</td><td>使用该连接的地址和 Key</td></tr><tr><td><code>providerId</code> 留空</td><td>跟随应用当前默认连接</td></tr><tr><td>Bot 的 <code>model</code> 非空</td><td>使用 Bot 明确填写的模型</td></tr><tr><td>Bot 的 <code>model</code> 留空</td><td>使用所选命名连接的默认模型</td></tr><tr><td>最终没有有效模型名</td><td>拒绝请求，要求先填写模型</td></tr></tbody></table><p>例如，研究 Bot 可选择“研究服务”连接与模型 A，写作 Bot 选择另一条连接与模型 B。它们仍保留各自的身份、会话、文件与记忆。切换模型不会新建 Bot，也不会自动开启工具。</p><p>编辑一条命名连接的地址、Key 或默认模型，会影响所有引用该连接的 Bot。若只想调整其中一个 Bot 的服务，先新建另一条连接，再分配给它。切换到另一地址来源时，需要明确填写该服务的 Key，程序不会把旧地址的密钥自动带过去。</p><p>工具轮次开始时会固定模型、温度、地址和凭据。中途修改配置影响后续轮次；运行记录保留该轮实际使用的模型。失败不会静默改用另一服务。</p><h2 id="配置结构与源码排查" tabindex="-1">配置结构与源码排查 <a class="header-anchor" href="#配置结构与源码排查" aria-label="Permalink to &quot;配置结构与源码排查&quot;">​</a></h2><p>日常使用界面保存配置。开发排错时，可以对照 <code>src/config.js</code> 和主进程的 <code>botApiSettings</code>；下面只展示结构，不包含可用凭据：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;profiles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;research-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;研究服务&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;baseUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-model-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;activeProfileId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;research-api&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>对应 Bot 使用 <code>providerId: &quot;research-api&quot;</code>。Bot 的 <code>model</code> 可明确指定，也可留空继承连接默认值。示例中的 <code>example.com</code> 和模型名必须替换，空 Key 不会产生回复。</p><p><code>config.json</code> 位于当前数据目录，权限为 <code>0600</code>。Key 由主进程使用，界面只取得掩码。默认连接也支持 <code>OPENBOT_API_KEY</code>、<code>OPENBOT_API_BASE</code> 等环境变量；命名连接不会借用环境变量中的凭据。不要把真实 Key 写进源码、Fleet 包或终端历史。</p><h2 id="自建节点使用哪条连接" tabindex="-1">自建节点使用哪条连接 <a class="header-anchor" href="#自建节点使用哪条连接" aria-label="Permalink to &quot;自建节点使用哪条连接&quot;">​</a></h2><p>Bot 选择“自建节点”后，日常聊天仍在 Mac；派给节点的任务使用节点数据目录中的模型配置。节点必须存在相同 ID 的 Bot，并配置自己的连接、模型、内核与工具权限。</p><p>Fleet 配置包保留 Bot 的 <code>providerId</code>、模型和内核，但不携带模型 Key。导入后在节点重新配置连接；本机显示“已接入”不能证明节点已准备好。完整步骤见<a href="/openbot/deployment/self-host.html">自建 Linux Node</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>下一步</th></tr></thead><tbody><tr><td>接口可达但没有模型回复</td><td>检查模型 ID、Key 权限、服务额度与服务端返回的错误</td></tr><tr><td>提示找不到 API 配置</td><td>重新为 Bot 选择存在的命名连接，检查 <code>providerId</code> 是否对应</td></tr><tr><td>仍使用旧模型</td><td>核对 Bot 的显式模型是否覆盖连接默认模型，并开始新一轮请求</td></tr><tr><td>切换服务后提示缺少 Key</td><td>为新地址明确填写 Key，再保存与重新检测</td></tr><tr><td>聊天正常，浏览器任务失败</td><td>检查模型图像/工具兼容性、工具开关与当前<a href="/openbot/guide/harness.html">内核组合</a></td></tr></tbody></table><p>下一步可阅读<a href="/openbot/guide/harness.html">执行内核</a>；准备让多个 Bot 协作时，继续<a href="/openbot/guide/jarvis.html">贾维斯模式</a>。</p>`,26)])])}const E=a(d,[["render",o]]);export{c as __pageData,E as default};
